const m = document.querySelector('.menu'), n = document.querySelector('.links'); if (m && n) { m.onclick = () => n.classList.toggle('open'); n.querySelectorAll('a').forEach(a => a.onclick = () => n.classList.remove('open')) } const o = new IntersectionObserver(es => es.forEach(e => e.isIntersecting && e.target.classList.add('show')), { threshold: .12 }); document.querySelectorAll('.reveal').forEach(e => o.observe(e)); const f = document.querySelector('#contactForm'); if (f) f.onsubmit = e => { e.preventDefault(); f.reset(); document.querySelector('.success').style.display = 'block' }; document.querySelectorAll('[data-year]').forEach(e => e.textContent = new Date().getFullYear());
